abstract class PortalReadModel {
    public const VERSION='portal_lesson_v1';
    protected function field(array $row,string $key){if(!array_key_exists($key,$row))throw new \InvalidArgumentException('portal_upstream_aggregate_invalid');return$row[$key];}
}

