    public function fromOwner(array $row):array { return array('version'=>self::VERSION,'lesson_uid'=>$this->field($row,'lesson_uid'),'reference_code'=>$this->field($row,'lesson_reference'),'lesson_kind'=>$this->field($row,'lesson_kind'),'lifecycle_state'=>$this->field($row,'lifecycle_state'),'enrolment_uid'=>$this->field($row,'enrolment_uid'),'course_reference'=>$this->field($row,'course_reference'),'term_reference'=>$this->field($row,'term_reference'),'starts_at_utc'=>$this->field($row,'starts_at_utc'),'ends_at_utc'=>$this->field($row,'ends_at_utc'),'schedule_timezone'=>$this->field($row,'schedule_timezone'),'schedule_version_uid'=>$this->field($row,'schedule_version_uid'),'delivery_state_summary'=>$this->field($row,'delivery_state_summary'),'attendance_state_summary'=>$this->field($row,'attendance_state_summary'),'join_available'=>(bool)$this->field($row,'join_available'),'join_refusal_reason'=>$this->field($row,'join_refusal_reason'),'absence_available'=>(bool)$this->field($row,'absence_available'),'absence_refusal_reason'=>$this->field($row,'absence_refusal_reason')); }
}

